import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
// IMPORT HỆ SINH THÁI API ĐÃ TẬP TRUNG TỪ FILE api.js
import { productsApi, categoriesApi, cartsApi } from '../services/api';

const Home = () => {
    const navigate = useNavigate();

    // --- 1. STATE LƯU DỮ LIỆU ĐỘNG TỪ DB ---
    const [products, setProducts] = useState([]);
    const [categories, setCategories] = useState([]);
    const [bestsellers, setBestsellers] = useState([]); // Sản phẩm nổi bật

    const [activeTab, setActiveTab] = useState('All Products');
    const [cartCount, setCartCount] = useState(0);
    const [heroSearch, setHeroSearch] = useState('');
    const [activeSlide, setActiveSlide] = useState(0);
    const [currentUser, setCurrentUser] = useState(null);

    // --- 2. EFFECT: CAROUSEL BANNER & ĐỌC LOCALSTORAGE ---
    useEffect(() => {
        // Tự động chuyển Banner
        const timer = setInterval(() => {
            setActiveSlide((prev) => (prev === 0 ? 1 : 0));
        }, 3000);

        // Đọc User an toàn
        const userString = localStorage.getItem('user');
        if (userString && userString !== "undefined" && userString !== "null") {
            try {
                setCurrentUser(JSON.parse(userString));
            } catch (e) {
                console.error("Lỗi đọc LocalStorage", e);
                localStorage.removeItem('user');
            }
        }

        return () => clearInterval(timer);
    }, []);

    const nextSlide = () => setActiveSlide((prev) => (prev === 0 ? 1 : 0));
    const prevSlide = () => setActiveSlide((prev) => (prev === 0 ? 1 : 0));

    // --- 3. EFFECT: GỌI API LẤY DATA THẬT BẰNG AXIOS ---
    useEffect(() => {
        // Tải Danh mục (Categories) cho các Tab
        categoriesApi.getAll()
            .then(res => setCategories(res.data))
            .catch(err => console.log("Lỗi tải Danh mục: ", err));

        // Tải toàn bộ Sản phẩm
        productsApi.getAll({ pageSize: 50 })
            .then(res => setProducts(res.data.items || res.data))
            .catch(err => console.log("Lỗi tải Sản phẩm: ", err));

        // Tải Sản phẩm Bán chạy / Nổi bật
        productsApi.getFeatured()
            .then(res => setBestsellers(res.data))
            .catch(err => console.log("Lỗi tải Bestseller: ", err));

        // Lấy số đếm Giỏ hàng nếu đã đăng nhập
        if (currentUser) {
            const userId = currentUser.userId || currentUser.id || currentUser.userName;
            cartsApi.getByUserId(userId)
                .then(res => setCartCount(res.data.length || 0))
                .catch(err => console.log("Lỗi đếm giỏ hàng: ", err));
        }
    }, [currentUser]);

    // --- 4. LOGIC LỌC SẢN PHẨM THEO TAB ---
    const filteredProducts = products.filter(item => {
        if (activeTab === 'All Products') return true;
        const catName = item.categoryName || item.category?.name || '';
        return catName.toLowerCase() === activeTab.toLowerCase();
    });

    // Lọc riêng vài món Rau Củ cho cái Carousel ngang (Giả sử category là Vegetables)
    const vegetablesList = products.filter(item =>
        (item.categoryName || item.category?.name || '').toLowerCase() === 'vegetables'
    );

    // --- 5. LOGIC CHỐT ĐƠN VÀO GIỎ HÀNG ---
    const handleAddToCart = async (e, product) => {
        e.preventDefault();

        if (!currentUser) {
            alert("Vui lòng đăng nhập để có thể mua hàng!");
            navigate('/login');
            return;
        }

        try {
            const userId = currentUser.userId || currentUser.id || currentUser.userName;
            await cartsApi.addToCart({
                userId: userId,
                productId: product.id,
                quantity: 1
            });

            alert(`Đã bế em "${product.name}" vào giỏ hàng thành công! 🛒`);
            setCartCount(prev => prev + 1);
        } catch (error) {
            console.error("Lỗi thêm giỏ hàng:", error);
            alert("Lỗi kết nối máy chủ, không thể thêm vào giỏ!");
        }
    };

    const handleHeroSearch = () => {
        const closeBtn = document.getElementById('close-search-modal');
        if (closeBtn) closeBtn.click();
        navigate('/shop', { state: { searchTerm: heroSearch } });
    };

    return (
        <>
            {/* --- NAVBAR & MODAL TÌM KIẾM (GIỮ NGUYÊN) --- */}
            <div className="container-fluid fixed-top">
                <div className="container px-0">
                    <nav className="navbar navbar-light bg-white navbar-expand-xl">
                        <Link to="/" className="navbar-brand"><h1 className="text-primary display-6">Fruitables</h1></Link>
                        <button className="navbar-toggler py-2 px-3" type="button" data-bs-toggle="collapse" data-bs-target="#navbarCollapse">
                            <span className="fa fa-bars text-primary"></span>
                        </button>
                        <div className="collapse navbar-collapse bg-white" id="navbarCollapse">
                            <div className="navbar-nav mx-auto">
                                <Link to="/" className="nav-item nav-link active">Home</Link>
                                <Link to="/shop" className="nav-item nav-link">Shop</Link>
                                <div className="nav-item dropdown">
                                    <a href="#" className="nav-link dropdown-toggle" data-bs-toggle="dropdown">Pages</a>
                                    <div className="dropdown-menu m-0 bg-secondary rounded-0">
                                        <Link to="/cart" className="dropdown-item">Cart</Link>
                                        <Link to="/checkout" className="dropdown-item">Checkout</Link>
                                    </div>
                                </div>
                                <Link to="/contact" className="nav-item nav-link">Contact</Link>
                            </div>
                            <div className="d-flex m-3 me-0">
                                <button className="btn-search btn border border-secondary btn-md-square rounded-circle bg-white me-4" data-bs-toggle="modal" data-bs-target="#searchModal">
                                    <i className="fas fa-search text-primary"></i>
                                </button>
                                <Link to="/cart" className="position-relative me-4 my-auto">
                                    <i className="fa fa-shopping-bag fa-2x"></i>
                                    <span className="position-absolute bg-secondary rounded-circle d-flex align-items-center justify-content-center text-dark px-1" style={{ top: '-5px', left: '15px', height: '20px', minWidth: '20px' }}>
                                        {cartCount}
                                    </span>
                                </Link>

                                {/* LOGIC USER LOGOUT / LOGIN */}
                                {currentUser ? (
                                    <div className="nav-item dropdown my-auto">
                                        <a href="#" className="nav-link dropdown-toggle d-flex align-items-center" data-bs-toggle="dropdown" style={{ padding: 0 }}>
                                            <i className="fas fa-user fa-2x text-success"></i>
                                            <span className="ms-2 fw-bold text-dark">{currentUser.name || currentUser.userName}</span>
                                        </a>
                                        <div className="dropdown-menu m-0 bg-secondary rounded-0">
                                            {(currentUser.role === 'Admin' || currentUser.Role === 'Admin') && (
                                                <Link to="/dashboard" className="dropdown-item fw-bold text-warning"><i className="fas fa-cog me-2"></i>Admin Dashboard</Link>
                                            )}
                                            <a href="#" className="dropdown-item" onClick={(e) => { e.preventDefault(); localStorage.clear(); window.location.reload(); }}>
                                                <i className="fas fa-sign-out-alt me-2"></i>Đăng xuất
                                            </a>
                                        </div>
                                    </div>
                                ) : (
                                    <Link to="/login" className="my-auto"><i className="fas fa-user fa-2x"></i></Link>
                                )}
                            </div>
                        </div>
                    </nav>
                </div>
            </div>

            <div className="modal fade" id="searchModal" tabIndex="-1" aria-labelledby="exampleModalLabel" aria-hidden="true">
                <div className="modal-dialog modal-fullscreen">
                    <div className="modal-content rounded-0">
                        <div className="modal-header">
                            <h5 className="modal-title" id="exampleModalLabel">Search by keyword</h5>
                            <button type="button" id="close-search-modal" className="btn-close" data-bs-dismiss="modal" aria-label="Close"></button>
                        </div>
                        <div className="modal-body d-flex align-items-center">
                            <div className="input-group w-75 mx-auto d-flex">
                                <input type="search" className="form-control p-3" placeholder="keywords" value={heroSearch} onChange={(e) => setHeroSearch(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleHeroSearch()} />
                                <span className="input-group-text p-3" style={{ cursor: 'pointer' }} onClick={handleHeroSearch}><i className="fa fa-search"></i></span>
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            {/* --- HERO BANNER --- */}
            <div className="container-fluid py-5 mb-5 hero-header">
                <div className="container py-5 mt-5">
                    <div className="row g-5 align-items-center">
                        <div className="col-md-12 col-lg-7">
                            <h4 className="mb-3 text-secondary">100% Organic Foods</h4>
                            <h1 className="mb-5 display-3 text-primary">Organic Veggies & Fruits Foods</h1>
                            <div className="position-relative mx-auto">
                                <input className="form-control border-2 border-secondary w-75 py-3 px-4 rounded-pill" type="text" placeholder="Search..." value={heroSearch} onChange={(e) => setHeroSearch(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleHeroSearch()} />
                                <button type="button" onClick={handleHeroSearch} className="btn btn-primary border-2 border-secondary py-3 px-4 position-absolute rounded-pill text-white h-100" style={{ top: 0, right: '25%' }}>Submit Now</button>
                            </div>
                        </div>
                        <div className="col-md-12 col-lg-5">
                            <div id="carouselId" className="carousel slide position-relative">
                                <div className="carousel-inner" role="listbox">
                                    <div className={`carousel-item rounded ${activeSlide === 0 ? 'active' : ''}`} style={{ transition: 'opacity 0.5s ease-in-out' }}>
                                        <img src="/img/hero-img-1.png" className="img-fluid w-100 h-100 bg-secondary rounded" alt="First slide" />
                                        <Link to="/shop" className="btn px-4 py-2 text-white rounded">Fruits</Link>
                                    </div>
                                    <div className={`carousel-item rounded ${activeSlide === 1 ? 'active' : ''}`} style={{ transition: 'opacity 0.5s ease-in-out' }}>
                                        <img src="/img/hero-img-2.jpg" className="img-fluid w-100 h-100 rounded" alt="Second slide" />
                                        <Link to="/shop" state={{ category: 'Vegetables' }} className="btn px-4 py-2 text-white rounded">Vegetables</Link>
                                    </div>
                                </div>
                                <button className="carousel-control-prev" type="button" onClick={prevSlide}><span className="carousel-control-prev-icon" aria-hidden="true"></span><span className="visually-hidden">Previous</span></button>
                                <button className="carousel-control-next" type="button" onClick={nextSlide}><span className="carousel-control-next-icon" aria-hidden="true"></span><span className="visually-hidden">Next</span></button>
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            {/* --- KHU VỰC 1: TAB SẢN PHẨM THEO DANH MỤC (LẤY TỪ DB) --- */}
            <div className="container-fluid fruite py-5">
                <div className="container py-5">
                    <div className="tab-class text-center">
                        <div className="row g-4">
                            <div className="col-lg-4 text-start">
                                <h1>Our Organic Products</h1>
                            </div>
                            <div className="col-lg-8 text-end">
                                <ul className="nav nav-pills d-inline-flex text-center mb-5">
                                    <li className="nav-item">
                                        <a className={`d-flex m-2 py-2 bg-light rounded-pill ${activeTab === 'All Products' ? 'active' : ''}`} data-bs-toggle="pill" href="#" onClick={(e) => { e.preventDefault(); setActiveTab('All Products'); }}>
                                            <span className="text-dark" style={{ width: '130px' }}>All Products</span>
                                        </a>
                                    </li>
                                    {categories.map((cat) => (
                                        <li className="nav-item" key={cat.id}>
                                            <a className={`d-flex m-2 py-2 bg-light rounded-pill ${activeTab === cat.name ? 'active' : ''}`} data-bs-toggle="pill" href="#" onClick={(e) => { e.preventDefault(); setActiveTab(cat.name); }}>
                                                <span className="text-dark" style={{ width: '130px' }}>{cat.name}</span>
                                            </a>
                                        </li>
                                    ))}
                                </ul>
                            </div>
                        </div>

                        {/* VẼ DANH SÁCH SẢN PHẨM TRONG TAB */}
                        <div className="tab-content">
                            <div className="tab-pane fade show p-0 active">
                                <div className="row g-4">
                                    <div className="col-lg-12">
                                        <div className="row g-4">
                                            {filteredProducts.slice(0, 8).map((item) => (
                                                <div className="col-md-6 col-lg-4 col-xl-3" key={item.id}>
                                                    <div className="rounded position-relative fruite-item h-100 d-flex flex-column">
                                                        <div className="fruite-img">
                                                            <Link to={`/shop-detail/${item.id}`}>
                                                                <img src={item.imageUrl || "/img/fruite-item-5.jpg"} className="img-fluid w-100 rounded-top" alt={item.name} style={{ height: '200px', objectFit: 'cover' }} />
                                                            </Link>
                                                        </div>
                                                        <div className="text-white bg-secondary px-3 py-1 rounded position-absolute" style={{ top: '10px', left: '10px' }}>
                                                            {item.categoryName || 'Sản phẩm'}
                                                        </div>
                                                        <div className="p-4 border border-secondary border-top-0 rounded-bottom flex-grow-1 d-flex flex-column">
                                                            <h4>{item.name}</h4>
                                                            <p className="flex-grow-1">{item.description ? item.description.substring(0, 50) + '...' : 'Sản phẩm tươi ngon'}</p>
                                                            <div className="d-flex justify-content-between flex-lg-wrap mt-auto">
                                                                <p className="text-dark fs-5 fw-bold mb-0">${item.price} / kg</p>
                                                                <a href="#" onClick={(e) => handleAddToCart(e, item)} className="btn border border-secondary rounded-pill px-3 text-primary">
                                                                    <i className="fa fa-shopping-bag me-2 text-primary"></i> Add to cart
                                                                </a>
                                                            </div>
                                                        </div>
                                                    </div>
                                                </div>
                                            ))}
                                            {filteredProducts.length === 0 && (
                                                <h4 className="text-center w-100 mt-5">Chưa có sản phẩm nào trong danh mục này! 😥</h4>
                                            )}
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            {/* --- KHU VỰC 2: RAU CỦ QUẢ (CAROUSEL DẠNG LƯỚI BÌNH THƯỜNG DO BOOTSTRAP CAROUSEL CẦN JQUERY) --- */}
            <div className="container-fluid vesitable py-5">
                <div className="container py-5">
                    <h1 className="mb-0">Fresh Organic Vegetables</h1>
                    <div className="row g-4 mt-3">
                        {vegetablesList.slice(0, 4).map(item => (
                            <div className="col-md-6 col-lg-4 col-xl-3" key={item.id}>
                                <div className="border border-primary rounded position-relative vesitable-item h-100 d-flex flex-column">
                                    <div className="vesitable-img">
                                        <Link to={`/shop-detail/${item.id}`}>
                                            <img src={item.imageUrl || "img/vegetable-item-6.jpg"} className="img-fluid w-100 rounded-top" alt="" style={{ height: '200px', objectFit: 'cover' }} />
                                        </Link>
                                    </div>
                                    <div className="text-white bg-primary px-3 py-1 rounded position-absolute" style={{ top: '10px', right: '10px' }}>
                                        {item.categoryName}
                                    </div>
                                    <div className="p-4 rounded-bottom flex-grow-1 d-flex flex-column">
                                        <h4>{item.name}</h4>
                                        <p className="flex-grow-1">{item.description ? item.description.substring(0, 50) + '...' : ''}</p>
                                        <div className="d-flex justify-content-between flex-lg-wrap mt-auto">
                                            <p className="text-dark fs-5 fw-bold mb-0">${item.price} / kg</p>
                                            <a href="#" onClick={(e) => handleAddToCart(e, item)} className="btn border border-secondary rounded-pill px-3 text-primary">
                                                <i className="fa fa-shopping-bag me-2 text-primary"></i> Add
                                            </a>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>

            {/* --- BANNER --- */}
            <div className="container-fluid banner bg-secondary my-5">
                <div className="container py-5">
                    <div className="row g-4 align-items-center">
                        <div className="col-lg-6">
                            <div className="py-4">
                                <h1 className="display-3 text-white">Fresh Exotic Fruits</h1>
                                <p className="fw-normal display-3 text-dark mb-4">in Our Store</p>
                                <p className="mb-4 text-dark">Chúng tôi cung cấp các loại trái cây tươi ngon, nhập khẩu và organic 100%.</p>
                                <Link to="/shop" className="banner-btn btn border-2 border-white rounded-pill text-dark py-3 px-5">BUY</Link>
                            </div>
                        </div>
                        <div className="col-lg-6">
                            <div className="position-relative">
                                <img src="/img/baner-1.png" className="img-fluid w-100 rounded" alt="" />
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            {/* --- KHU VỰC 3: BESTSELLER (SẢN PHẨM NỔI BẬT TỪ API) --- */}
            <div className="container-fluid py-5">
                <div className="container py-5">
                    <div className="text-center mx-auto mb-5" style={{ maxWidth: '700px' }}>
                        <h1 className="display-4">Bestseller Products</h1>
                        <p>Những sản phẩm được khách hàng yêu thích và mua nhiều nhất trong tuần qua.</p>
                    </div>
                    <div className="row g-4">
                        {bestsellers.slice(0, 6).map(item => (
                            <div className="col-lg-6 col-xl-4" key={item.id}>
                                <div className="p-4 rounded bg-light h-100">
                                    <div className="row align-items-center">
                                        <div className="col-6">
                                            <Link to={`/shop-detail/${item.id}`}>
                                                <img src={item.imageUrl || "img/best-product-1.jpg"} className="img-fluid rounded-circle w-100" style={{ height: '130px', objectFit: 'cover' }} alt="" />
                                            </Link>
                                        </div>
                                        <div className="col-6">
                                            <Link to={`/shop-detail/${item.id}`} className="h5 text-dark">{item.name}</Link>
                                            <div className="d-flex my-2">
                                                <i className="fas fa-star text-primary"></i>
                                                <i className="fas fa-star text-primary"></i>
                                                <i className="fas fa-star text-primary"></i>
                                                <i className="fas fa-star text-primary"></i>
                                                <i className="fas fa-star"></i>
                                            </div>
                                            <h4 className="mb-3">${item.discountPrice > 0 ? item.discountPrice : item.price}</h4>
                                            <a href="#" onClick={(e) => handleAddToCart(e, item)} className="btn border border-secondary rounded-pill px-3 text-primary">
                                                <i className="fa fa-shopping-bag me-2 text-primary"></i> Add to cart
                                            </a>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>

            {/* --- FOOTER & TỔNG KẾT --- */}
            <div className="container-fluid copyright bg-dark py-4">
                <div className="container">
                    <div className="row">
                        <div className="col-md-6 text-center text-md-start mb-3 mb-md-0">
                            <span className="text-light"><a href="#"><i className="fas fa-copyright text-light me-2"></i>Fruitables System</a>, All right reserved.</span>
                        </div>
                        <div className="col-md-6 my-auto text-center text-md-end text-white">
                            Designed By HTML Codex
                        </div>
                    </div>
                </div>
            </div>

            <a href="#" className="btn btn-primary border-3 border-primary rounded-circle back-to-top"><i className="fa fa-arrow-up"></i></a>
        </>
    );
};

export default Home;
